mapper.select:
select

from sys_dict d
left join sys_dict_type t on d.type_code = t.type_code and d.tenant_id = t.tenant_id
left join sys_module m on t.module_code = m.module_code and t.tenant_id = m.tenant_id
where d.tenant_id = #{tenantId}

    and d.type_code = #{typeCode}


    and t.module_code = #{moduleCode}

order by d.type_code, d.dict_order
